def distinct_islands(grid):
    R, C = len(grid), len(grid[0]) if grid else 0
    seen = set()
    shapes = set()
    for r in range(R):
        for c in range(C):
            if grid[r][c] == 1 and (r, c) not in seen:
                stack, cells = [(r, c)], []
                seen.add((r, c))
                while stack:
                    y, x = stack.pop()
                    cells.append((y - r, x - c))
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
